// Compile Time: Template Instantiation (charT=char)
std::string input = "data: 100, data: 200";
std::regex pattern("(\\d+)"); // Traits=std::regex_traits<char>

// T=char, ST=std::string, SA=std::allocator<char>
// std::regex_replace<T, Traits<T>, ST, SA>(...)

std::string replacement = "{$1}";

// Runtime: Pattern matching and replacement execution
std::string result = std::regex_replace(input, pattern, replacement);

// result == "data: {100}, data: {200}"
